INSERT INTO terms_and_conditions (title, content_ur, is_active, sort_order) SELECT 'بینک کی مکمل ادائیگی', 'بینک پر خریدار کو دیا گیا ریٹ صرف اسی صورت میں لاگو ہوگا جب وہ اس بینک کی پوری رقم ادا کرے۔', 1, 1 WHERE NOT EXISTS (SELECT 1 FROM terms_and_conditions WHERE content_ur = 'بینک پر خریدار کو دیا گیا ریٹ صرف اسی صورت میں لاگو ہوگا جب وہ اس بینک کی پوری رقم ادا کرے۔');
INSERT INTO terms_and_conditions (title, content_ur, is_active, sort_order) SELECT 'جزوی ادائیگی', 'اگر بینک کی رقم جزوی ادا کی جائے تو بینک کا ریٹ صرف ادا شدہ رقم کے مطابق مال پر لاگو ہوگا۔', 1, 2 WHERE NOT EXISTS (SELECT 1 FROM terms_and_conditions WHERE content_ur = 'اگر بینک کی رقم جزوی ادا کی جائے تو بینک کا ریٹ صرف ادا شدہ رقم کے مطابق مال پر لاگو ہوگا۔');
INSERT INTO terms_and_conditions (title, content_ur, is_active, sort_order) SELECT 'بقیہ مال کا ریٹ', 'بقیہ رقم/بینک کے بقیہ مال پر مارکیٹ کا نیا ریٹ لاگو ہوگا۔', 1, 3 WHERE NOT EXISTS (SELECT 1 FROM terms_and_conditions WHERE content_ur = 'بقیہ رقم/بینک کے بقیہ مال پر مارکیٹ کا نیا ریٹ لاگو ہوگا۔');
INSERT INTO terms_and_conditions (title, content_ur, is_active, sort_order) SELECT 'فرق کی اطلاع', 'اگر کسی قسم کا کوئی فرق پایا جائے تو 10 دن کے اندر رابطہ کریں۔', 1, 4 WHERE NOT EXISTS (SELECT 1 FROM terms_and_conditions WHERE content_ur = 'اگر کسی قسم کا کوئی فرق پایا جائے تو 10 دن کے اندر رابطہ کریں۔');
INSERT INTO terms_and_conditions (title, content_ur, is_active, sort_order) SELECT 'واپسی یا تبدیلی', 'مال واپس یا تبدیل نہیں ہوگا، سوائے ڈیلیوری کے وقت ثابت شدہ نقص کے۔', 1, 5 WHERE NOT EXISTS (SELECT 1 FROM terms_and_conditions WHERE content_ur = 'مال واپس یا تبدیل نہیں ہوگا، سوائے ڈیلیوری کے وقت ثابت شدہ نقص کے۔');
INSERT INTO terms_and_conditions (title, content_ur, is_active, sort_order) SELECT 'اتروائی کے بعد ذمہ داری', 'اتروائی کے بعد مال کی ٹوٹ پھوٹ، نقصان یا چوری کی ذمہ داری کمپنی پر نہیں۔', 1, 6 WHERE NOT EXISTS (SELECT 1 FROM terms_and_conditions WHERE content_ur = 'اتروائی کے بعد مال کی ٹوٹ پھوٹ، نقصان یا چوری کی ذمہ داری کمپنی پر نہیں۔');
INSERT INTO terms_and_conditions (title, content_ur, is_active, sort_order) SELECT 'ادھار کی ادائیگی', 'ادھار کی صورت میں بقایا رقم باہمی طے شدہ مدت میں ادا کرنا لازم ہے۔', 1, 7 WHERE NOT EXISTS (SELECT 1 FROM terms_and_conditions WHERE content_ur = 'ادھار کی صورت میں بقایا رقم باہمی طے شدہ مدت میں ادا کرنا لازم ہے۔');
